// validateChasmSideEffectTask completes validation of a CHASM side effect task
// after mutable state load/physical task validation.
func validateChasmSideEffectTask(
	ctx context.Context,
	ms historyi.MutableState,
	task *tasks.ChasmTask,
) (any, error) {
	// Because CHASM timers can target closed workflows, we need to specifically
	// exclude zombie workflows, instead of merely checking that the workflow is
	// running.
	if ms.GetExecutionState().State == enumsspb.WORKFLOW_EXECUTION_STATE_ZOMBIE {
		return nil, consts.ErrWorkflowZombie
	}

	tree := ms.ChasmTree()
	if tree == nil {
		return nil, errNoChasmTree
	}

	isValid, err := tree.ValidateSideEffectTask(ctx, task)
	if err == nil && isValid {
		// If the task is still valid, keep it around by returning a non-nil value.
		return &struct{}{}, nil
	}

	return nil, err
}

// executeChasmSideEffectTask completes execution of a CHASM side effect task
// after physical task validation.
//
// TODO - ExecuteSideEffectTask doesn't need to be on ChasmTree once path
// decoding is done at access time.
func executeChasmSideEffectTask(
	ctx context.Context,
	engine chasm.Engine,
	tree historyi.ChasmTree,
	task *tasks.ChasmTask,
) error {
	executionKey := chasm.ExecutionKey{
		NamespaceID: task.NamespaceID,
		BusinessID:  task.WorkflowID,
		RunID:       task.RunID,
	}

	engineCtx := chasm.NewEngineContext(ctx, engine)
	return tree.ExecuteSideEffectTask(
		engineCtx,
		executionKey,
		task,
		chasmSideEffectTaskValidateFn(task),
	)
}

// chasmSideEffectTaskValidateFn returns the access-time validation function used
// when executing or discarding a CHASM side effect task.
func chasmSideEffectTaskValidateFn(
	task *tasks.ChasmTask,
) func(chasm.NodeBackend, chasm.Context, chasm.Component) error {
	return func(backend chasm.NodeBackend, _ chasm.Context, _ chasm.Component) error {
		// Because CHASM timers can target closed workflows, we need to specifically
		// exclude zombie workflows, instead of merely checking that the workflow is
		// running.
		if backend.GetExecutionState().State == enumsspb.WORKFLOW_EXECUTION_STATE_ZOMBIE {
			return consts.ErrWorkflowZombie
		}

		// Validate task generation. We don't need to refresh tasks as we re-generate
		// CHASM tasks on transaction close.
		taskID := task.TaskID
		tgClock := backend.GetExecutionInfo().TaskGenerationShardClockTimestamp
		if tgClock != 0 && taskID != 0 && taskID < tgClock {
			return consts.ErrStaleReference
		}

		return nil
	}
}

// discardChasmSideEffectTask handles discard of a CHASM side effect task on
// standby clusters, once the task has been pending past the configured discard
// delay.
//
// It first checks whether the execution still exists on the source (active)
// cluster. If it is gone, there is nothing to discard and nil is returned.
// Otherwise, if the task's executor implements SideEffectTaskDiscarder, the
// registered discard handler is invoked; if it does not, the task is dropped by
// returning consts.ErrTaskDiscarded.
func discardChasmSideEffectTask(
	ctx context.Context,
	engine chasm.Engine,
	registry *chasm.Registry,
	tree historyi.ChasmTree,
	task *tasks.ChasmTask,
	logger log.Logger,
	clusterName string,
	clientBean client.Bean,
	namespaceRegistry namespace.Registry,
) error {
	// If the execution no longer exists on the source cluster, the task was
	// already handled there and there is nothing to discard here.
	if !executionExistsOnSource(
		ctx,
		taskWorkflowKey(task),
		getTaskArchetypeID(task),
		logger,
		clusterName,
		clientBean,
		namespaceRegistry,
		registry,
	) {
		return nil
	}

	registrableTask, ok := registry.TaskByID(task.Info.GetTypeId())
	if !ok {
		return serviceerror.NewInternalf("unknown CHASM task type id: %d", task.Info.GetTypeId())
	}

	if !registrableTask.HasDiscardHandler() {
		logger.Warn("Discarding standby CHASM side effect task due to task being pending for too long.", tag.Task(task))
		return consts.ErrTaskDiscarded
	}

	executionKey := chasm.ExecutionKey{
		NamespaceID: task.NamespaceID,
		BusinessID:  task.WorkflowID,
		RunID:       task.RunID,
	}

	engineCtx := chasm.NewEngineContext(ctx, engine)
	return tree.ExecuteSideEffectDiscardTask(
		engineCtx,
		executionKey,
		task,
		chasmSideEffectTaskValidateFn(task),
	)
}
